using System;using System.Windows.Forms;
namespace ScoreModern {
 public static class NativePrintMenuChoice {
  static bool configuredNative=NativeSettings.Read("print-menu")=="native";
  public static bool Original{get{return NativeScoreBehaviour.Enabled||!configuredNative;}}
  internal static void Set(bool original,bool save){configuredNative=!original;if(save)NativeSettings.WriteAllText("print-menu",original?"score":"native");}
  internal static void AddMenu(ContextMenuStrip menu){var score=new ToolStripMenuItem("F6 menu: SCORE format");var native=new ToolStripMenuItem("F6 menu: PNG/EPS F-buttons");score.ToolTipText=native.ToolTipText="Applies the next time F6 opens. The strict SCORE preset always uses SCORE format.";score.Click+=(s,e)=>Set(true,true);native.Click+=(s,e)=>Set(false,true);menu.Items.Add(score);menu.Items.Add(native);menu.Opening+=(s,e)=>{score.Checked=Original;native.Checked=!Original;native.Enabled=!NativeScoreBehaviour.Enabled;};}
 }
 public sealed partial class Editor {
  bool originalPrintMenuActive=true;
  bool UsesOriginalPrintMenu{get{return NativeScoreBehaviour.Enabled||originalPrintMenuActive;}}
  void NativeExportPrintFunction(int key){if(key==1)Reference();else if(key==2)Print();else if(key==3)ExportResolution(3840);else if(key==4)ExportResolution(7680);else if(key==5)ExportPrintEps();else if(key==6)LoadPrintSettings();else if(key==7)SavePrintSettings();else if(key==8){mode=ScreenMode.Main;LayoutClassic();}UpdateClassic();}
  internal void CheckOriginalPrintKeyboard(){var bytes=score.Encode();NativePrintMenuChoice.Set(true,false);EnterOriginalPrintMenu();Application.DoEvents();if(!originalPrintEntry.Focused)throw new Exception("Print entry lacks focus.");string hidden=command.Text;var typed=new KeyPressEventArgs('6');OnKeyPress(typed);if(typed.Handled||command.Text!=hidden)throw new Exception("Print character was stolen by Main command routing.");var home=new KeyEventArgs(Keys.Home);OnKeyDown(home);if(home.SuppressKeyPress)throw new Exception("Print Home was intercepted by main viewport routing.");originalPrintEntry.Text="6 600";OnKeyDown(new KeyEventArgs(Keys.Enter));if(printJob.Resolution!=600||originalPrintEntry.Text!="")throw new Exception("Print Enter did not apply typed control.");OriginalPrintKey(new KeyEventArgs(Keys.Escape));if(!System.Linq.Enumerable.SequenceEqual(bytes,score.Encode()))throw new Exception("Print keyboard changed notation.");Console.WriteLine("PASS print entry focus, character ownership, Home and typed Enter through Form events.");}
  internal void CheckPrintMenuChoices(){bool before=NativePrintMenuChoice.Original,strict=NativeScoreBehaviour.Enabled;try{NativeScoreBehaviour.Set(false,false);NativePrintMenuChoice.Set(false,false);Function(6);if(mode!=ScreenMode.Print||UsesOriginalPrintMenu||originalPrintPanel!=null&&originalPrintPanel.Visible)throw new Exception("Native F6 choice failed.");Function(8);if(mode!=ScreenMode.Main)throw new Exception("Native F6 exit failed.");NativePrintMenuChoice.Set(true,false);Function(6);if(!UsesOriginalPrintMenu||originalPrintPanel==null||!originalPrintPanel.Visible)throw new Exception("SCORE F6 choice failed.");OriginalPrintKey(new KeyEventArgs(Keys.Escape));NativePrintMenuChoice.Set(false,false);NativeScoreBehaviour.Set(true,false);Function(6);if(!UsesOriginalPrintMenu||!NativePrintMenuChoice.Original)throw new Exception("Strict preset lost SCORE F6 menu.");OriginalPrintKey(new KeyEventArgs(Keys.Escape));Console.WriteLine("PASS SCORE/native F6 choices, exit and strict preset.");}finally{NativeScoreBehaviour.Set(strict,false);NativePrintMenuChoice.Set(before,false);}}
 }
 public static class NativePrintMenuChoiceChecks {public static int Run(string root){try{using(var editor=new Editor(root,System.IO.Path.Combine(root,"MUSDAT","PRACTICE.MUS"))){editor.Show();Application.DoEvents();editor.CheckOriginalPrintKeyboard();editor.CheckPrintMenuChoices();editor.Close();}return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}
}
